INSERT INTO venues (
    slug, id, name, town, county, country, status, hero_asset_id,
    seo_title, seo_description, document_json, updated_at
  ) VALUES (
    'leighinmohr-house-hotel', 'venue_5b2ae5d2-2997-440a-ae4b-18ebac50a7d6', 'Leighinmohr house hotel',
    'Ballymena', 'Co. Antrim', 'Northern Ireland', 'published',
    'legacy_8e1aae4c8046ded362aa9a0f', '',
    '', '{"schemaVersion":1,"id":"venue_5b2ae5d2-2997-440a-ae4b-18ebac50a7d6","slug":"leighinmohr-house-hotel","name":"Leighinmohr house hotel","county":"Co. Antrim","town":"Ballymena","intro":"","description":"Leighinmohr House Hotel has a calm, understated charm that makes wedding days feel relaxed and effortless. From a Northern Ireland wedding photographer’s perspective, it’s the kind of venue where the day naturally falls into place, without the need for heavy direction or staging. The hotel blends classic elegance with a warm, welcoming atmosphere, helping couples and guests feel at ease from the early morning preparations through to the evening celebrations.  The gardens and surrounding grounds offer a variety of beautifully contained spaces for portraits, allowing photography to flow smoothly without ever pulling you too far from the heart of the day. Mature trees, soft greenery and thoughtfully kept outdoor areas provide a mix of structure and openness, perfect for both intimate couple portraits and relaxed group shots. Inside, the character of the house adds depth and atmosphere, creating timeless backdrops that suit every stage of the celebration. Set just moments from Ballymena town centre, Leighinmohr House Hotel offers a real sense of continuity to a wedding day. Everything happens within easy reach, which keeps the pace unhurried and the experience connected.","heroImageId":"legacy_8e1aae4c8046ded362aa9a0f","status":"published","links":{"website":"https://leighinmohrhotel.com","instagram":"","facebook":"","googleMaps":""},"contact":{"email":"","phone":"","coordinatorName":"","coordinatorEmail":""},"practical":{"address":"","parking":"","accommodation":"","ceremonyTypes":"","capacity":"","outdoorCeremony":false},"notes":{"general":"","portraitLocations":"","rainBackup":"","sunsetNotes":"","restrictions":""},"seo":{"title":"","description":""},"createdAt":"2026-07-12T09:18:54.748Z","updatedAt":"2026-07-14T13:04:50.162Z","country":"Northern Ireland"}', '2026-07-13T07:52:28.332Z'
  ) ON CONFLICT(slug) DO UPDATE SET
    id=excluded.id, name=excluded.name, town=excluded.town, county=excluded.county,
    country=excluded.country, status=excluded.status, hero_asset_id=excluded.hero_asset_id,
    seo_title=excluded.seo_title, seo_description=excluded.seo_description,
    document_json=excluded.document_json, updated_at=excluded.updated_at;

