  ) VALUES (
    'orange-tree-house-summer-wedding-ian-and-bernadette', 'legacy-story', 'A stylish, relaxed wedding at Orange Tree House, Greyabbey', 'Ian & Bernadette', 'Orange Tree House',
    'orange-tree-house', '', 'May 2026', 'Ian and Bernadette celebrated their long-awaited wedding at Orange Tree House in Greyabbey, enjoying glorious sunshine, stunning views across Strangford Lough and a relaxed atmosphere surrounded by family and friends', 'Some weddings feel effortlessly special from the moment you arrive, and Ian and Bernadette''s day at Orange Tree House was certainly one of them. After many years together, they finally said ''I do'' in one of Northern Ireland''s most sought-after wedding venues, with sunshine, laughter and incredible scenery creating the perfect setting.',
    'published', 1, 'published', NULL, 'Orange Tree House Wedding Photography | Greyabbey Wedding Photographer | MKB Weddings', 'View Ian and Bernadette''s beautiful Orange Tree House wedding in Greyabbey.',
    '{"schemaVersion":1,"slug":"orange-tree-house-summer-wedding-ian-and-bernadette","title":"A stylish, relaxed wedding at Orange Tree House, Greyabbey","couple":"Ian & Bernadette","venue":"Orange Tree House","weddingDate":"May 2026","excerpt":"Ian and Bernadette celebrated their long-awaited wedding at Orange Tree House in Greyabbey, enjoying glorious sunshine, stunning views across Strangford Lough and a relaxed atmosphere surrounded by family and friends","intro":"Some weddings feel effortlessly special from the moment you arrive, and Ian and Bernadette''s day at Orange Tree House was certainly one of them. After many years together, they finally said ''I do'' in one of Northern Ireland''s most sought-after wedding venues, with sunshine, laughter and incredible scenery creating the perfect setting.","story":["The day began in a wonderfully relaxed atmosphere as preparations took place at Orange Tree House...","Following an emotional ceremony, guests enjoyed drinks outdoors while making the most of the exceptional weather...","For couples planning a wedding at Orange Tree House, it is easy to see why this venue is so highly regarded."],"facts":{"season":"Spring","ceremonyType":"Religious Ceremony","ceremonyLocation":"Orange Tree House","receptionLocation":"Orange Tree House","celebrant":"Briege Flood","photographer":"MKB Weddings"},"suppliers":[{"role":"Photography","name":"MKB Weddings","instagram":"mkbweddings","website":"https://www.mkbweddings.co.uk"},{"role":"Venue","name":"Orange Tree House","instagram":"orangetreeweddings"},{"role":"Flowers","name":"Chelseas creations","instagram":"chelseascreationsni"},{"role":"Decor","name":"Chelseas creations","instagram":"chelseascreationsni"}],"venueSlug":"orange-tree-house","seo":{"title":"Orange Tree House Wedding Photography | Greyabbey Wedding Photographer | MKB Weddings","description":"View Ian and Bernadette''s beautiful Orange Tree House wedding in Greyabbey."},"status":"published","storyEnabled":true,"storyStatus":"published"}', CURRENT_TIMESTAMP
  ) ON CONFLICT(slug) DO NOTHING;

