    ai_tags_json = CASE WHEN excluded.ai_tags_json <> '[]' THEN excluded.ai_tags_json ELSE images.ai_tags_json END,
    source_type = CASE WHEN excluded.source_type <> '' THEN excluded.source_type ELSE images.source_type END,
